window.BloomHelpData.register({"schema":1,"locale":"tr","nativeReviewRequired":true,"common":{"review":"Taslak çeviri. Ana dili konuşuru tarafından incelenmesi gerekiyor.","fallback":"Bazı yardım metinleri İngilizce gösteriliyor.","recovery":"Bir sorun olduğunda","availability":"Entegrasyon adayıdır; onaylanan derlemede desteği doğrulayın."},"routes":{"start":{"title":"Yeni sekme / başlangıç sayfası","summary":"Kayıtlı bir siteyi açın veya bir adres girin.","step":"Bir kutucuk seçin, ardından Aç seçeneğini kullanın. Başka bir siteye gitmek için adres alanını kullanın.","recovery":"Kutucuk çalışmazsa çalıştığını bildiğiniz herkese açık bir sayfayı deneyin ve ağ bağlantınızı kontrol edin."},"passwords":{"title":"Parola yöneticisi (prototip arayüz; kasa yerel uygulama bileşenidir)","summary":"Kayıtlı oturum açma bilgilerini dikkatli kullanın.","step":"Kayıtlı bir hesabı seçmeden önce web sitesi adresini kontrol edin.","recovery":"Kasa kilitliyse desteklenen işlemle kilidini açın. Destek raporuna asla parola eklemeyin."},"settings":{"title":"Ayarlar","summary":"Gezinme tercihlerinizi ayarlayın.","step":"Her seferinde tek bir ayarı değiştirip sonucu kontrol edin.","recovery":"Onaylı bir test planını izlemiyorsanız deneysel JIT ve GPU ayarlarını kapalı tutun."},"https-only":{"title":"Yalnızca HTTPS modu"},"private":{"title":"Gizli gezinme"},"themes":{"title":"Ortak temalar"},"reader":{"title":"Okuma modu","summary":"Bir makaleyi daha az dikkat dağıtıcı öğeyle okuyun.","step":"Geçerli makale için Okuyucu’yu açın ve kullanılabilir metin kontrollerini ayarlayın.","recovery":"Bazı sayfaların içeriği çıkarılamaz; içerik eksikse özgün sayfaya dönün."},"media":{"title":"Medya Merkezi"},"downloads":{"title":"İndirmeler paneli","summary":"İndirmeleri izleyin ve yönetin.","step":"Her işin durumunu ve hedefini kontrol edin; dosyaları yalnızca indirme tamamlandıktan sonra açın.","recovery":"Bir iş başarısız olursa hata mesajını kaydedin. JDownloader isteğe bağlıdır ve Setup kontrollerini geçmelidir."},"notes":{"title":"Notlar"},"device-login":{"title":"Başka bir cihazda oturum açın"},"status":{"title":"Bloom Core durumu","summary":"Paketin hangi uygulamalarının yanıt verdiğini kontrol edin.","step":"Her uygulamayı açmadan önce durumunu okuyun.","recovery":"Bloom Core çalışmıyorsa ortak uygulama keşfi kullanılamayabilir; gösterilen hatayı saklayın."},"library":{"title":"Yer işaretleri ve geçmiş","summary":"Kaydedilmiş bağlantıları ve tarama geçmişini bulun.","step":"Yer İşaretleri veya Geçmiş’i seçin ve bir sonucu açmadan önce adresi kontrol edin.","recovery":"Yerel bir kaydı silmek, bir web sitesi hesabını veya o hesaba ait kayıtları kaldırmaz."},"translate":{"title":"Sayfayı çevir","summary":"Sayfayı İngilizce okuyun.","step":"Web sitesi adresini ve Google Translate bilgilendirmesini inceleyin. Yalnızca sayfa adresini göndermeyi kabul ediyorsanız devam edin.","recovery":"Sayfa değişirse bu paneli yeniden açın ve yeni sayfayı onaylayın. Çeviri hatalı olabilir; hassas içerik göndermekten kaçının."}}});
